option.value:
html,
body {
    width: 100%;
    height: 100%;
    margin: 0;
}

body {
    overflow: hidden;
    background: #000;
    color: #fff;
    font-family: Arial, Helvetica, sans-serif;
}

.heading {
    position: relative;
    text-align: center;
    top: 1rem;
    left: 50%;
    transform: translateX(-50%);
    font-size: 2rem;
    font-weight: 600;
    background: rgba(0, 0, 0, 0.45);
    padding: 0.5rem 1rem;
    border-radius: 0.75rem;
}
.app-shell {
    position: relative;
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    background: #000;
}

.app-shell__image {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: contain;
    object-position: center center;
    user-select: none;
    -webkit-user-drag: none;
    pointer-events: none;
}

.hotspot-layer {
    position: absolute;
    inset: 0;
}

.hotspot {
    position: absolute;
    display: block;
    border: 2px solid rgba(255, 255, 255, 0.0);
    background: rgba(0, 153, 255, 0.0);
    border-radius: 10px;
    text-decoration: none;
    cursor: pointer;
    outline: none;
    transition: background-color 140ms ease, border-color 140ms ease, box-shadow 140ms ease, transform 140ms ease;
}

.hotspot:hover,
.hotspot:focus-visible {
    background: rgba(0, 153, 255, 0.18);
    border-color: rgba(255, 255, 255, 0.65);
    box-shadow: 0 0 0 2px rgba(0, 153, 255, 0.35);
    transform: scale(1.01);
}

/* Visible hotspot styled as a standard button */
.hotspot.visible {
    pointer-events: auto;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    color: #fff;
    background: linear-gradient(180deg, #16a909 0%, #0a7e0d 100%);
    border-color: rgba(255,255,255,0.12);
    box-shadow: 0 6px 18px rgba(2,132,199,0.28), inset 0 -2px 0 rgba(255,255,255,0.06);
    font-weight: 600;
    font-size: 1.1rem;
    padding: 0.5rem 0.9rem;
    border-radius: 12px;
    text-decoration: none;
}

.hotspot.visible:focus {
    box-shadow: 0 0 0 4px rgba(2,132,199,0.25);
    transform: translateY(-1px);
}

/* keep the textual tooltip only for non-visible hotspots */
.hotspot:not(.visible)::after { opacity: 0; }
.hotspot:not(.visible):hover::after,
.hotspot:not(.visible):focus-visible::after { opacity: 1; }

.hotspot::after {
    content: attr(data-label);
    position: absolute;
    left: 50%;
    bottom: 100%;
    transform: translate(-50%, -0.4rem);
    padding: 0.35rem 0.55rem;
    border-radius: 999px;
    background: rgba(0, 0, 0, 0.65);
    color: #fff;
    font-size: 0.78rem;
    line-height: 1;
    white-space: nowrap;
    opacity: 0;
    pointer-events: none;
    transition: opacity 140ms ease;
}

.hotspot:hover::after,
.hotspot:focus-visible::after {
    opacity: 1;
}

.hint {
    position: absolute;
    left: 1rem;
    bottom: 1rem;
    z-index: 2;
    padding: 0.65rem 0.9rem;
    border-radius: 0.75rem;
    background: rgba(0, 0, 0, 0.45);
    backdrop-filter: blur(4px);
    font-size: 0.95rem;
    line-height: 1.4;
    max-width: min(26rem, calc(100vw - 2rem));
}

.text-card {
    position: fixed;      /* stays in place when scrolling */
    top: 20px;            /* distance from top */
    right: 200px;          /* distance from right */
    width: 850px;
    padding: 10px;
    background: rgb(255 255 255 / 0.28);
    border: 1px solid rgb(221 221 221 / 0);
    border-radius: 10px;
    box-shadow: 0 4px 10px rgba(0,0,0,0.15);
}

.button {
  pointer-events: auto;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    color: #fff;
    background: linear-gradient(180deg, #16a909 0%, #0a7e0d 100%);
    border-color: rgba(255,255,255,0.12);
    box-shadow: 0 6px 18px rgba(2,132,199,0.28), inset 0 -2px 0 rgba(255,255,255,0.06);
    font-weight: 600;
    font-size: 1.1rem;
    padding: 0.5rem 0.9rem;
    border-radius: 12px;
    text-decoration: none;
}

@media (max-width: 700px) {
    .hint {
        right: 1rem;
        font-size: 0.85rem;
    }
}

.sun-spectrum-layout {
    box-sizing: border-box;
    width: 100%;
    min-height: 100%;
    padding: 2rem;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 1.25rem;
    color: #fff;
    margin-top: 1rem;
  }

  .sun-spectrum-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1.5rem;
    align-items: start;
  }

  .sun-spectrum-card {
    background: rgb(255 255 255 / 0.63);
    border: 2px solid rgba(255, 255, 255, 0.15);
    border-radius: 12px;
    padding: 1rem;
  }

  .sun-spectrum-card h2 {
    margin: 0 0 0.75rem;
    font-size: 1.2rem;
    text-align: center;
  }

  .sun-spectrum-card img {
    width: 100%;
    height: min(52vh, 420px);
    object-fit: contain;
    border-radius: 8px;
  }


  .sun-spectrum-note {
    margin: 0;
    text-align: left;
    font-size: 1rem;
    line-height: 1.5;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    padding: 0.85rem 1rem;
  }

  @media (max-width: 900px) {
    .sun-spectrum-layout {
        padding: 1rem;
    }

    .sun-spectrum-grid {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    .sun-spectrum-card img {
        height: min(38vh, 320px);
    }
  }

